  animation-delay: 0.5s;
}

.sds-loader-mosaic > *:nth-child(7) {
  animation-delay: 0.6s;
}

.sds-loader-mosaic > *:nth-child(8) {
  animation-delay: 0.7s;
}

.sds-loader-mosaic > *:nth-child(9) {
  animation-delay: 0.8s;
}

